{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$defs": {
    "NumberFromString": {
      "type": "string",
      "description": "a string to be decoded into a number"
    }
  },
  "type": "object",
  "required": [
    "id",
    "name",
    "price"
  ],
  "properties": {
    "id": {
      "type": "number"
    },
    "name": {
      "type": "string"
    },
    "price": {
      "$ref": "#/$defs/NumberFromString"
    }
  },
  "additionalProperties": false
}

